#include <stdio.h>
int main(void) {
    // 처음에는 포장 가능 표시를 꺼 두어요.
    int stock = 4;
    int group = 3;
    int ready = 0;
    // 이 주석 아래에 재고가 충분할 때만 ready를 1로 바꾸는 if 문을 쓰세요.
    // 조건이 맞을 때만 중괄호 안이 실행돼요. 모자라면 ready는 처음 값 0 그대로예요.
    if (stock >= group) {
        ready = 1;
    }
    printf("%d", ready);
    return 0;
}

