#include <stdio.h>
int main(void) {
    // 재고 일곱 개를 세 개씩 나눠요.
    int stock = 7;
    int group = 3;
    int packs = stock / group;
    int left = stock % group;
    int display;
    if (left == 0) {
        display = 0;
    } else {
        // 이 줄을 고쳐 한 묶음을 더 채우는 데 필요한 개수를 담으세요.
        // 한 묶음은 group개예요. 이미 left개가 있으니 group - left개가 더 필요해요.
        display = group - left;
    }
    printf("%d\n", packs);
    printf("%d", display);
    return 0;
}

