#include <stdio.h>
int main(void) {
    int stock = 11;
    int size = 4;
    // 완성한 상자 수와 다음 상자에 부족한 낱개 수를 계산하세요.
    int boxes = stock / size;
    int missing = stock % size == 0 ? 0 : size - stock % size;
